const { isPositive, classify } = require("./index");

test("isPositive returns true for positive numbers", () => {
  expect(isPositive(1)).toBe(true);
});

test("isPositive returns false for zero", () => {
  expect(isPositive(0)).toBe(false);
});

test("isPositive returns false for negative numbers", () => {
  expect(isPositive(-5)).toBe(false);
});

test("classify maps negatives to negative", () => {
  expect(classify(-3)).toBe("negative");
});

test("classify maps positives to positive", () => {
  expect(classify(3)).toBe("positive");
});

test("classify maps zero to zero", () => {
  expect(classify(0)).toBe("zero");
});
